/**
 * Geographic reference data (GeoNames, CC BY 4.0) — cities ≥ 50k people plus
 * every national capital, and all countries. Indexes are built lazily once per
 * isolate. Generated by `scripts/build-geodata.mjs`.
 */
import citiesData from '../../data/cities.json';
import countriesData from '../../data/countries.json';

export interface City {
  id: number;
  name: string;
  slug: string;
  lat: number;
  lon: number;
  cc: string;
  admin1: string;
  region: string | undefined;
  population: number;
  timezone: string;
  isCapital: boolean;
  /** Part of the global snapshot used by the map and world rankings. */
  monitored: boolean;
  /** A section of a larger city (GeoNames PPLX), e.g. Puxi in Shanghai. */
  isDistrict: boolean;
}

export interface Country {
  cc: string;
  name: string;
  slug: string;
  continent: ContinentCode;
  population: number;
}

export type ContinentCode = 'AF' | 'AS' | 'EU' | 'NA' | 'OC' | 'SA' | 'AN';

export const CONTINENTS: Record<ContinentCode, string> = {
  AF: 'Africa',
  AS: 'Asia',
  EU: 'Europe',
  NA: 'North America',
  OC: 'Oceania',
  SA: 'South America',
  AN: 'Antarctica',
};

/** A location the dashboard can report on: a known city, or a geocoded place. */
export interface Place {
  kind: 'city' | 'place';
  id: number | null;
  slug: string;
  name: string;
  region?: string | undefined;
  cc: string;
  country: string;
  lat: number;
  lon: number;
  timezone: string;
  population?: number | undefined;
}

type CityRow = [number, string, string, number, number, string, string, number, number, number];
type CountryRow = [string, string, string, string, number];

interface Index {
  cities: City[];
  bySlug: Map<string, City>;
  byId: Map<number, City>;
  byCountry: Map<string, City[]>;
  countries: Country[];
  countryByCode: Map<string, Country>;
  countryBySlug: Map<string, Country>;
  aliases: Record<string, string>;
  admin1: Record<string, string>;
  searchKeys: string[];
}

let index: Index | null = null;

export function normalize(s: string): string {
  return s
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

export function slugify(s: string): string {
  return normalize(s).replace(/\s+/g, '-');
}

function build(): Index {
  const tz = citiesData.tz as unknown as string[];
  const admin1 = citiesData.admin1 as unknown as Record<string, string>;
  const cities: City[] = (citiesData.rows as unknown as CityRow[]).map((r) => ({
    id: r[0],
    name: r[1],
    slug: r[2],
    lat: r[3],
    lon: r[4],
    cc: r[5],
    admin1: r[6],
    region: admin1[`${r[5]}.${r[6]}`],
    population: r[7],
    timezone: tz[r[8]] ?? 'UTC',
    isCapital: (r[9] & 1) === 1,
    monitored: (r[9] & 2) === 2,
    isDistrict: (r[9] & 4) === 4,
  }));
  const bySlug = new Map(cities.map((c) => [c.slug, c]));
  const byId = new Map(cities.map((c) => [c.id, c]));
  const byCountry = new Map<string, City[]>();
  for (const c of cities) {
    const list = byCountry.get(c.cc);
    if (list) list.push(c);
    else byCountry.set(c.cc, [c]);
  }
  const countries: Country[] = (countriesData.rows as unknown as CountryRow[]).map((r) => ({
    cc: r[0],
    name: r[1],
    slug: r[2],
    continent: r[3] as ContinentCode,
    population: r[4],
  }));
  return {
    cities,
    bySlug,
    byId,
    byCountry,
    countries,
    countryByCode: new Map(countries.map((c) => [c.cc, c])),
    countryBySlug: new Map(countries.map((c) => [c.slug, c])),
    aliases: citiesData.aliases as unknown as Record<string, string>,
    admin1,
    searchKeys: cities.map((c) => normalize(c.name)),
  };
}

function idx(): Index {
  return (index ??= build());
}

// ---------------------------------------------------------------------------
// Lookups
// ---------------------------------------------------------------------------

export function getCityBySlug(slug: string): City | undefined {
  return idx().bySlug.get(slug);
}

/** Canonical slug for an alias such as "new-york" or "gurgaon". */
export function resolveAlias(slug: string): string | undefined {
  return idx().aliases[slug];
}

/** Whether `name` is this city's name or a known former/alternative one ("Gurgaon" → Gurugram). */
export function isCityNamed(city: City, name: string): boolean {
  return normalize(city.name) === normalize(name) || resolveAlias(slugify(name)) === city.slug;
}

export function getCityById(id: number): City | undefined {
  return idx().byId.get(id);
}

export function getCountry(cc: string): Country | undefined {
  return idx().countryByCode.get(cc.toUpperCase());
}

export function getCountryBySlug(slug: string): Country | undefined {
  return idx().countryBySlug.get(slug);
}

export function allCountries(): readonly Country[] {
  return idx().countries;
}

export function countryName(cc: string): string {
  return getCountry(cc)?.name ?? cc;
}

export function regionName(cc: string, admin1: string): string | undefined {
  return idx().admin1[`${cc}.${admin1}`];
}

/**
 * Distinct cities for rankings: no districts, and nothing within `minKm` of a
 * more populous city already chosen (the model grid would repeat its reading).
 */
export function distinctCities(list: readonly City[], limit: number, minKm = 20): City[] {
  const chosen: City[] = [];
  for (const c of list) {
    if (c.isDistrict) continue;
    if (chosen.some((m) => distanceKm(m.lat, m.lon, c.lat, c.lon) < minKm)) continue;
    chosen.push(c);
    if (chosen.length >= limit) break;
  }
  return chosen;
}

/** Cities in a country, most populous first. */
export function citiesInCountry(cc: string): readonly City[] {
  return idx().byCountry.get(cc.toUpperCase()) ?? [];
}

/** Regions (admin1) of a country that contain at least one city in the dataset. */
export function regionsInCountry(cc: string): Array<{ code: string; name: string; cities: number }> {
  const counts = new Map<string, number>();
  for (const c of citiesInCountry(cc)) counts.set(c.admin1, (counts.get(c.admin1) ?? 0) + 1);
  return [...counts.entries()]
    .map(([code, cities]) => ({ code, name: regionName(cc, code) ?? '', cities }))
    .filter((r) => r.name)
    .sort((a, b) => a.name.localeCompare(b.name));
}

export function monitoredCities(): readonly City[] {
  return idx().cities.filter((c) => c.monitored);
}

export function allCities(): readonly City[] {
  return idx().cities;
}

export function cityToPlace(c: City): Place {
  return {
    kind: 'city',
    id: c.id,
    slug: c.slug,
    name: c.name,
    region: c.region,
    cc: c.cc,
    country: countryName(c.cc),
    lat: c.lat,
    lon: c.lon,
    timezone: c.timezone,
    population: c.population,
  };
}

// ---------------------------------------------------------------------------
// Distance & proximity
// ---------------------------------------------------------------------------

export function distanceKm(aLat: number, aLon: number, bLat: number, bLon: number): number {
  const R = 6371;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(bLat - aLat);
  const dLon = toRad(bLon - aLon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function nearestCity(lat: number, lon: number): { city: City; distanceKm: number } | null {
  let best: City | null = null;
  let bestD = Infinity;
  for (const c of idx().cities) {
    // Cheap bounding pre-filter before the haversine.
    if (Math.abs(c.lat - lat) > 5 && bestD < 500) continue;
    const d = distanceKm(lat, lon, c.lat, c.lon);
    if (d < bestD) {
      bestD = d;
      best = c;
    }
  }
  return best ? { city: best, distanceKm: bestD } : null;
}

export function citiesNear(
  lat: number,
  lon: number,
  opts: { radiusKm: number; limit: number; excludeId?: number | null; monitoredOnly?: boolean },
): Array<{ city: City; distanceKm: number }> {
  const out: Array<{ city: City; distanceKm: number }> = [];
  for (const c of idx().cities) {
    if (opts.monitoredOnly && !c.monitored) continue;
    if (c.id === opts.excludeId) continue;
    const d = distanceKm(lat, lon, c.lat, c.lon);
    if (d <= opts.radiusKm) out.push({ city: c, distanceKm: d });
  }
  return out.sort((a, b) => a.distanceKm - b.distanceKm).slice(0, opts.limit);
}

// ---------------------------------------------------------------------------
// Local search (instant; complements remote geocoding)
// ---------------------------------------------------------------------------

export interface LocalMatch<T> {
  item: T;
  score: number;
}

function matchScore(key: string, q: string): number {
  if (key === q) return 3;
  if (key.startsWith(q)) return 2;
  if (key.includes(` ${q}`)) return 1;
  return 0;
}

export function searchCities(query: string, limit = 8): City[] {
  const q = normalize(query);
  if (q.length < 2) return [];
  const { cities, searchKeys, aliases, bySlug } = idx();
  const matches: Array<LocalMatch<City>> = [];
  for (let i = 0; i < cities.length; i++) {
    const s = matchScore(searchKeys[i]!, q);
    if (s > 0) matches.push({ item: cities[i]!, score: s });
  }
  // Former / alternative names ("gurgaon", "bombay"): exact match ranks first, prefix match after.
  const qSlug = q.replace(/\s+/g, '-');
  for (const [alias, slug] of Object.entries(aliases)) {
    const exact = alias === qSlug;
    if (!exact && !(q.length >= 3 && alias.startsWith(qSlug))) continue;
    const city = bySlug.get(slug);
    if (city) matches.push({ item: city, score: exact ? 3 : 2 });
  }
  const seen = new Set<number>();
  return matches
    .sort((a, b) => b.score - a.score || b.item.population - a.item.population)
    .map((m) => m.item)
    .filter((c) => (seen.has(c.id) ? false : (seen.add(c.id), true)))
    .slice(0, limit);
}

export function searchCountries(query: string, limit = 3): Country[] {
  const q = normalize(query);
  if (q.length < 2) return [];
  return idx()
    .countries.map((c) => ({ item: c, score: matchScore(normalize(c.name), q) || (c.cc.toLowerCase() === q ? 2 : 0) }))
    .filter((m) => m.score > 0)
    .sort((a, b) => b.score - a.score || b.item.population - a.item.population)
    .slice(0, limit)
    .map((m) => m.item);
}

export function searchRegions(query: string, limit = 3): Array<{ cc: string; code: string; name: string }> {
  const q = normalize(query);
  if (q.length < 3) return [];
  const out: Array<{ cc: string; code: string; name: string; score: number; size: number }> = [];
  for (const [key, name] of Object.entries(idx().admin1)) {
    const s = matchScore(normalize(name), q);
    if (s === 0) continue;
    const [cc, code] = key.split('.') as [string, string];
    const size = citiesInCountry(cc).filter((c) => c.admin1 === code).length;
    out.push({ cc, code, name, score: s, size });
  }
  return out.sort((a, b) => b.score - a.score || b.size - a.size).slice(0, limit);
}
